  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';

  for (const { column, cards } of boardState) {
    const columnEl = createColumnElement(column, cards);
    boardEl.appendChild(columnEl);
  }

  setupDropZones();
}

