// --- SSE Real-time Updates ---
function connectSSE() {
  const statusEl = document.getElementById('status');

  // Disconnect existing connection
  if (sse) {
    sse.close();
  }

  sse = new EventSource(`${API_BASE}/stream`);

  sse.onopen = () => {
    statusEl.innerHTML = '<span class="connected">●</span> Connected';
