  sse.addEventListener('cardCreated', (e) => {
    const data = JSON.parse(e.data);
    handleCardCreated(data);
  });

  // Card moved event
  sse.addEventListener('cardMoved', (e) => {
    const data = JSON.parse(e.data);
    handleCardMoved(data);
  });

