// Initialize database and start server
initDatabase().then(() => {
  console.log('Database initialized');
  app.listen(PORT, () => {
    console.log(`Kanban backend running on http://localhost:${PORT}`);
  });
}).catch(err => {
  console.error('Failed to initialize database:', err);
  process.exit(1);
});
