  addBtn.addEventListener('click', () => {
    const text = input.value.trim();
    if (text) {
      input.value = '';
      actions.style.display = 'none';
      createCard(column.id, text);
    }
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      const text = input.value.trim();
      if (text) {
        input.value = '';
        actions.style.display = 'none';
        createCard(column.id, text);
      }
    }
    if (e.key === 'Escape') {
      input.value = '';
      actions.style.display = 'none';
      input.blur();
    }
  });

  colEl.appendChild(form);

  return colEl;
}

