      flex: 1;
      overflow-y: auto;
      min-height: 40px;
      padding: 2px;
    }

    .cards-container.drag-over {
      background: rgba(0, 0, 0, 0.05);
      border-radius: 8px;
    }

    .card {
      background: white;
      border-radius: 8px;
      padding: 8px 12px;
      margin-bottom: 8px;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
