async function init() {
  try {
    boardState = await fetchBoard();
    renderBoard();
    connectSSE();
  } catch (err) {
    console.error('Failed to initialize board:', err);
    document.getElementById('status').innerHTML = '<span class="disconnected">●</span> Failed to connect to server';
