      gap: 16px;
      padding: 20px;
      overflow-x: auto;
      min-height: calc(100vh - 60px);
      align-items: flex-start;
    }

    .column {
      background: #ebecf0;
      border-radius: 12px;
      min-width: 280px;
      max-width: 280px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      max-height: calc(100vh - 100px);
    }

